   Check(total==2040&&peak==270&&g.Elite&&g.Elite.ChargeAttack,"Camp budget or elite wrong");foreach(var e in g.Enemies.Where(z=>z.Alive&&!z.IsElite).Skip(1).ToArray())e.Health.Kill();var boss=g.Elite;var attack=boss.ChargeAttack;float hp=g.PlayerHealth.CurrentHealth;
