   yield return new WaitForSeconds(.4f);boss.Agent.Warp(new Vector3(0,0,7));Move(Vector3.zero);attack.Initialize(g,boss);t=Time.time+2;attack.Tick(t);g.PlayerHealth.BeginDodge(3);attack.Tick(t+g.Chapter.eliteWindup+.01f);deadline=Time.time+3;while(attack.Phase==EliteCharge.Stage.Charging&&Time.time<deadline){attack.Tick(t+g.Chapter.eliteWindup+.02f);yield return null;}Check(attack.Hits==0&&g.PlayerHealth.CurrentHealth==after,"Dodge immunity ignored");g.PlayerHealth.ClearDodge();
